"""Writes reference values for light deflection by the Sun, using pyerfa.

Run from the repository root with a Python that has `pyerfa` and `numpy`:

    python tpt-planetary-astro/tests/fixtures/gen_light_deflection_fixture.py

Writes `light_deflection_erfa.tsv`, one line per case:

    ra_deg dec_deg jd1 jd2 hx hy hz out_ra_deg out_dec_deg

where (ra, dec) is the ICRS direction of a distant source, (jd1, jd2) the TT
epoch, (hx, hy, hz) the observer's heliocentric position in AU from
`erfa.epv00`, and (out_ra, out_dec) the direction after light deflection by
the Sun from `erfa.ld` (bm = 1 solar mass, q = p for a source at infinity,
dlim = 1e-10). Sources are sampled over the whole sky, with extra weight near
the Sun, where the deflection is largest.
"""

import os

import erfa
import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))


def main():
    rng = np.random.default_rng(11)
    rows = []
    epochs = [(2451545.0, 0.0), (2460000.5, 0.25), (2415020.5, 0.0), (2488069.5, 0.5)]
    for jd1, jd2 in epochs:
        pvh, _ = erfa.epv00(jd1, jd2)
        helio = np.asarray(pvh[0], dtype=float)
        em = float(np.linalg.norm(helio))
        e = helio / em
        for k in range(15):
            if k < 10:
                # Sources within about 30 degrees of the Sun, seen from the observer.
                p = -e + rng.normal(size=3) * rng.uniform(0.05, 0.5)
            else:
                p = rng.normal(size=3)
            p = p / np.linalg.norm(p)
            if 1.0 + np.dot(p, e) < 1e-3:
                continue
            out = np.asarray(erfa.ld(1.0, p, p, helio / em, em, 1e-10), dtype=float)
            ra = np.degrees(np.arctan2(p[1], p[0])) % 360.0
            dec = np.degrees(np.arcsin(np.clip(p[2], -1.0, 1.0)))
            ora = np.degrees(np.arctan2(out[1], out[0])) % 360.0
            odec = np.degrees(np.arcsin(np.clip(out[2], -1.0, 1.0)))
            rows.append(
                "%.12f %.12f %.10f %.10f %.12e %.12e %.12e %.12f %.12f"
                % (ra, dec, jd1, jd2, helio[0], helio[1], helio[2], ora, odec)
            )
    path = os.path.join(HERE, "light_deflection_erfa.tsv")
    with open(path, "w") as f:
        f.write(
            "# ra_deg dec_deg jd1 jd2 hx hy hz (AU) out_ra_deg out_dec_deg; generated by pyerfa %s\n"
            % erfa.__version__
        )
        f.write("\n".join(rows) + "\n")
    print("wrote", len(rows), "cases to", path)


if __name__ == "__main__":
    main()
